"""Offline, self-contained HTML with honest discrete-date, zero-baseline charts."""
from html import escape
import json


def chart(result):
    # Separate bars at observed dates: no fabricated monthly path between endpoints.
    values=[('2024-10',100),('2026-10',result['laspeyres'])]
    parts=['<svg viewBox="0 0 680 300" role="img" aria-label="AWS five configuration Laspeyres index. October 2024: 100. October 2026: 84.596094. Linear axis from zero to 120.">']
    for tick in range(0,121,20):
        y=250-tick*1.75
        parts.append(f'<path d="M65 {y} H650" stroke="#dbe3ef"/><text x="52" y="{y+4}" text-anchor="end">{tick}</text>')
    for i,(label,v) in enumerate(values):
        x=170+i*280; h=v*1.75
        parts.append(f'<rect x="{x}" y="{250-h}" width="115" height="{h}" rx="5" fill="{["#6378a5","#1d776d"][i]}"/><text x="{x+57}" y="{240-h}" text-anchor="middle">{v:.6f}</text><text x="{x+57}" y="278" text-anchor="middle">{label}</text>')
    parts.append('</svg>')
    return ''.join(parts)


def table(rows, columns):
    return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+escape(c.replace('_',' '))+'</th>' for c in columns)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+escape(f'{r[c]:.6f}' if isinstance(r[c],float) else str(r[c]))+'</td>' for c in columns)+'</tr>' for r in rows)+'</tbody></table></div>'


def render(core,legacy,replacement,metrics,manifest):
    costs=replacement['quantities']; cost=replacement['replacement_cost']; diff=replacement['difference']
    rows=[r for r in metrics if r['validation']=='rolling_time' and r['shrinkage']==12]
    payload=json.dumps(dict(core=core,legacy=legacy,replacement=replacement),indent=2).replace('<','\\u003c')
    scan_note='A live bounded request scanned 2,096,924 bytes of the baseline archive, selected two raw instance-name matches (Windows reservation and Ubuntu Pro), and found zero qualifying core Linux rows in that prefix. The scan is incomplete and does not independently reproduce the endpoint tariffs.' if manifest.get('bounded_live_aws_scan') else 'No independent live archive verification is recorded for this build.'
    return f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>GPU rental price research • local prototype</title><style>
:root{{font-family:system-ui,sans-serif;color:#172d45;background:#f0f4f7}}body{{max-width:1100px;margin:auto;padding:36px 22px}}h1{{font-size:36px;margin-bottom:8px}}h2{{margin-top:30px;font-size:22px}}p{{line-height:1.6}}.eyebrow{{font-weight:700;color:#1d776d;letter-spacing:.09em}}.grid{{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px}}.card,section{{background:white;border:1px solid #dbe3ef;border-radius:14px;padding:22px;margin:16px 0}}.big{{font-size:32px;font-weight:700}}.tag{{display:inline-block;background:#e1f0ec;border-radius:6px;padding:4px 8px;font-weight:650}}.assumed{{background:#fff0cf}}.unavailable{{background:#edf0f4}}svg{{width:100%;max-height:420px}}svg text{{font:14px system-ui;fill:#29415a}}table{{border-collapse:collapse;width:100%;font-size:13px}}td,th{{padding:10px;text-align:left;border-bottom:1px solid #dde4ec}}th{{background:#edf3f7}}.scroll{{overflow-x:auto}}a{{color:#176f80}}details{{padding:14px}}code{{background:#edf3f7;padding:3px}}footer{{font-size:13px;color:#52667c}}
</style><header><div class="eyebrow">LOCAL RESEARCH PROTOTYPE · FORMULA v1</div><h1>GPU rental quote index</h1><p>Same configurations, explicit terms, visible evidence. Research vintage: 28 October 2026.</p></header>
<div class="grid"><div class="card"><span class="tag">OBSERVED tariffs</span><p>AWS five-configuration index</p><div class="big">{core['laspeyres']:.6f}</div><p>100 in October 2024 → October 2026<br>{core['laspeyres']-100:+.6f}% · equal baseline spending</p></div><div class="card"><span class="tag">OBSERVED tariffs</span><p>Matched cohort coverage</p><div class="big">5 / 5 · 100%</div><p>One provider · one region · on demand<br>0% modelled · 0% stale in this cohort</p></div><div class="card"><span class="tag unavailable">UNAVAILABLE</span><p>Broad-market fitted index</p><div class="big">Not estimated</div><p>No qualified monthly multi-provider panel. Availability and transaction weights unknown.</p></div></div>
<section><h2>Observed endpoint comparison</h2><p>Linear level axis begins at zero. Two effective-month endpoints only; no interpolated monthly history. Linux, shared tenancy, bundled instance hours, us-east-1. Publication: 4 November 2024 and 27 October 2026. These are retrospective October tariff comparisons, not information available on 1 October.</p>{chart(core)}<p>Laspeyres: 100 × Σ pᵢₜqᵢ₀ / Σ pᵢ₀qᵢ₀, with qᵢ₀ ∝ 1/pᵢ₀. Geometric reference: {core['geometric']:.6f}. The geometric measure is a reference comparator, not fixed-quantity dollar replacement cost.</p>{table(core['members'],['instance','gpu','baseline_price','target_price','ratio','baseline_expenditure_weight'])}<p>Prices are USD per complete instance hour. H100 and A100 each include eight GPU devices. The A100 configuration is the 40 GB variant. Capacity is unverified; advertised tariffs are not transaction prices.</p></section>
<section><h2>Separate cohort sensitivity</h2><p><span class="tag assumed">ASSUMED cohort choice</span> Adding V100, M60 and K80 gives <b>{legacy['laspeyres']:.6f}</b> ({legacy['laspeyres']-100:+.6f}%). Each of eight cells receives 12.5% baseline spending. This is not a revision of the five-cell series. L40S and A100 80 GB remain outside both published cohorts.</p></section>
<section><h2>$1 trillion fixed-quantity illustration</h2><p><span class="tag assumed">ASSUMED purchaser quantities</span> Allocate $200 billion of baseline spending to each of five configurations. Buy qᵢ = $200 billion / pᵢ₀ instance-hours. Reprice those exact quantities at the terminal tariffs.</p><div class="grid"><div><div class="big">${cost/1e9:,.3f} billion</div><p>Terminal replacement cost</p></div><div><div class="big">${diff/1e9:,.3f} billion</div><p>Arithmetic cost difference</p></div></div>{table(costs,['instance','baseline_spend','instance_hours','baseline_price','target_price','target_cost'])}<p>This does not establish feasible purchases, OpenAI contract value or realizable profit. No capacity, delivery schedule, prepayment, discounting or transfer rights are assumed. Quantities are instance-hours, not a $1 trillion hardware acquisition.</p></section>
<section><h2>Working model lab</h2><p><span class="tag assumed">SYNTHETIC TESTS ONLY</span> Seed 20261028; 30 months; three GPU types; AWS plus three fictional neoclouds. An AWS policy jump coexists with independent neocloud movements. No synthetic quote enters the observed indices.</p><p>Comparators: own-price random walk; constant AWS spread; partially pooled source/GPU spread changes; policy-adjusted separate-segment changes. Policy transmission is fixed at 1 for AWS and 0 for other providers in the last comparator. This is an identification assumption, not a measured coefficient.</p>{table(rows,['model','block','n','median_absolute_log_relative_error','p90_absolute_log_relative_error','coverage_90','mean_interval_score_90'])}<p>Expanding time origins, two nonoverlapping evaluation blocks, each neocloud held out from fitting, and shrinkage 6/12/24 are exported. Last held-out-provider price is allowed as a conditioning input. Next-month AWS tariff is supplied as a scenario: these are conditional price-change predictions, not advance forecasts of AWS policy. 90% normal intervals are diagnostic and may fail calibration. No model is promoted from these simulations.</p></section>
<section><h2>Financial calibration and separate interfaces</h2><p><span class="tag">OBSERVED filings</span> Supplied NVIDIA, Broadcom and neocloud fact vintages are preserved. The acceptance-time gate excludes future or missing acceptance timestamps. Financial predictors enter only the optional synthetic-rental challenger described below; they do not change the observed AWS arithmetic. TCO and equity challengers remain unimplemented. Filings do not identify rental prices.</p><p><span class="tag unavailable">SCAFFOLDED</span> Useful-work interface computes cost per accepted output for a qualified whole-system benchmark; no benchmark data supplied. Forward-contract interface records start, duration, cluster, prepayment and rights; valuation deliberately requires further evidence.</p></section>
<section><h2>Coverage, sources and licensing</h2><p>Observed series cover 5 of 5 declared cells, not 100% of the GPU market. The source extraction contains 10 configurations at two endpoints. No pre-launch fill, monthly carry, provider blending or spot/term substitution occurs.</p><p>Supplied matched CSV SHA256: <code>{manifest['inputs']['aws_gpu_2024_2026_expanded10.csv']['sha256']}</code>. This hash covers the research extraction; full archive bytes were not independently downloaded in this build. {scan_note} GPU interconnect, certain memory fields and launch dates remain explicitly unknown. Unknown fields do not prove full economic comparability beyond the stable SKU and bundle.</p><p><a href="https://pricing.us-east-1.amazonaws.com/offers/v1.0/aws/AmazonEC2/20241104205721/us-east-1/index.csv">Baseline AWS archive</a> · <a href="https://pricing.us-east-1.amazonaws.com/offers/v1.0/aws/AmazonEC2/20261027193004/us-east-1/index.csv">Terminal AWS archive</a>. AWS and catalog redistribution terms need review before external data-product publication. GetDeploying aggregates are composition-sensitive; no SiliconData or Ornn extraction is implemented.</p><p>Exports: <a href="quotes.csv">quotes</a> · <a href="index_summary.csv">indices</a> · <a href="cohort_members.csv">membership</a> · <a href="replacement_quantities.csv">quantity arithmetic</a> · <a href="synthetic_model_scores.csv">model scores</a> · <a href="summary.json">summary</a> · <a href="manifest.json">provenance</a>.</p></section>
<details><summary>Machine-readable result</summary><pre>{escape(payload)}</pre></details><footer>Offline report generated deterministically by gpu_index. Observed tariff evidence, fitted synthetic estimates, assumed scenarios and unavailable outputs retain separate labels.</footer></html>'''


def financial_section(scores,eligibility):
    scores=[r for r in scores if r['validation']=='rolling_time' and r['ridge']==24]
    return '<section><h2>Optional financial challengers · second implementation slice</h2><p><span class="tag">DERIVED FROM OBSERVED FILINGS</span> Annual log revenue growth uses current and prior annual periods from the same accession, tag and USD unit. A feature becomes usable after both the SEC acceptance timestamp and filed-date UTC day have passed. All forecast features are lagged to the end of the prior month. NVIDIA, Broadcom and CoreWeave retain distinct issuer-proxy blocks. These are consolidated-business proxies, not measured AI segments or compute prices. Nebius is disabled because its business perimeter is unqualified.</p><p><span class="tag assumed">SYNTHETIC RENTAL VALIDATION</span> Working ridge corrections use separate hyperscaler/neocloud coefficients, training-only standardization, mean imputation and no intercept. Each month has unit total regression weight per segment. Default ridge penalty is 24; no-finance, single-block and leave-block-out ablations are compared in expanding time windows. This report uses actual filing features with fictional rental paths. No financial challenger is promoted.</p>'+table(scores,['variant','block','n','median_absolute_log_relative_error','coverage_90','active_features_max'])+'<p><span class="tag unavailable">DATA ELIGIBILITY</span> '+str(eligibility['total_quotes'])+' endpoint quotes, '+str(eligibility['consecutive_monthly_pairs'])+' consecutive monthly pairs, '+str(eligibility['eligible_quotes'])+' qualified model rows under the default source manifest. Known monthly provider overlap, launch/interconnect details and source-rights qualification remain necessary. Import accepts normalized quote CSV plus explicit AWS anchor bindings and a source-rights manifest; it preserves configuration IDs and publication dates. See <a href="data_eligibility.csv">record-level exclusions</a>, <a href="financial_feature_vintages.csv">as-of financial features</a> and <a href="financial_challenger_scores.csv">challenger ablations</a>.</p></section>'
